def merge(intervals):
    intervals.sort(key=lambda x: x[0])
    res = []
    for i in intervals:
        if len(res) == 0:
            res.append(i)
        elif i[0] <= res[-1][1]:
            if i[1] > res[-1][1]:
                res[-1][1] = i[1]
        else:
            res.append(i)
    return res
